from voice_v3 import O,key,save
import httpx,json,base64
parts=[]
for i in [1,2]:parts.extend([{'text':f'Full narration part {i}; preserve same voice across both.'},{'inline_data':{'mime_type':'audio/mpeg','data':base64.b64encode((O/f'part-{i}.mp3').read_bytes()).decode()}}])
parts.append({'text':'Critically inspect actual audio for a mature US female car-selfie VSL, after user rejected prior voice as robotic. Evaluate natural speech, consistent identity across parts, robotic/announcer/singsong cadence, glitches, swallowed/clipped/repeated/added/missing words, pronunciations, and unnatural long pauses. Return JSON with voice_fit, naturalness_score_1_10, voice_consistency, concrete_issues [{part,start,end,issue}], pronunciation_notes, missing_added_words. Do not certify words merely because they appear in the supplied text; compare audible speech. Long non-speaking pauses will be trimmed in Resolve after this review. Exact script:\n'+(O/'narration-exact.txt').read_text()})
r=httpx.post('https://generativelanguage.googleapis.com/v1beta/models/gemini-3-flash-preview:generateContent',headers={'x-goog-api-key':key('GEMINI_API_KEY')},json={'contents':[{'parts':parts}],'generationConfig':{'temperature':0.1,'responseMimeType':'application/json'}},timeout=300);r.raise_for_status();j=r.json();save('full-voice-qa-response.json',j);print(j['candidates'][0]['content']['parts'][0]['text'])
